 "content": "from collections import Counter


def transform(grid):
    """Copy the non-background tile into every compartment separated by full lines."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    hcuts = [r for r, row in enumerate(grid)
             if len(set(row)) == 1 and row[0] != background]
    vcuts = [c for c in range(w)
             if len({grid[r][c] for r in range(h)}) == 1
             and grid[0][c] != background]

    # Separator lines must bound equal-sized compartments.
    row_ranges = []
    start = 0
    for r in hcuts:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in vcuts:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    tiles = []
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            tile = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(value != background for row in tile for value in row)
            tiles.append((score, ri, ci, tile))
    if not tiles:
        return [row[:] for row in grid]

    _, _, _, source = max(tiles, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for _, ri, ci, _ in tiles:
        r0, r1 = row_ranges[ri]
        c0, c1 = col_ranges[ci]
        if (r1 - r0, c1 - c0) != (len(source), len(source[0])):
            continue
        for dr in range(r1 - r0):
            out[r0 + dr][c0:c1] = source[dr][:]
    return out


if __name__ == "__main__":
    test = [[5, 5, 5], [5, 5, 5], [8, 8, 8], [7, 7, 5], [5, 4, 5]]
    print(transform(test))
